INSERT INTO `astrologer_page_items` VALUES (1,'chat','feature','100% Genuine',NULL,'Only verified experts with a proven track record. Trusted for over <strong>2 Million+</strong> consultations worldwide.','star',1,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(2,'chat','feature','Master Astrologers',NULL,'Selected through a strict <strong>4-step interview process</strong> to ensure accurate predictions every single time.','graduation',2,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(3,'chat','feature','First Chat Free',NULL,'Talk to our best experts for free. Get 100% secure, private, and <strong>confidential guidance</strong> anytime.','check-circle',3,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(4,'chat','verify_step','Background & KYC Checks',NULL,'We strictly verify government documents, real identity, and address before any astrologer is considered.',NULL,4,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(5,'chat','verify_step','Certification Review',NULL,'Astrological degrees, authentic lineage proof, and years of valid experience are thoroughly evaluated.',NULL,5,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(6,'chat','verify_step','Live Assessment Panel',NULL,'Candidates face a tough, real-time consultation test conducted by our in-house veteran astrologers.',NULL,6,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(7,'chat','verify_step','Quality Monitoring',NULL,'Approved experts undergo a strict trial period where consultations are continuously audited for accuracy.',NULL,7,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(8,'chat','topic','Finding true love & soulmate compatibility',NULL,NULL,NULL,8,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(9,'chat','topic','Perfect timing for marriage & Kundli analysis',NULL,NULL,NULL,9,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(10,'chat','topic','Navigating career shifts & promotion timelines',NULL,NULL,NULL,10,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(11,'chat','topic','Wealth creation & strategic business investments',NULL,NULL,NULL,11,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(12,'chat','topic','Resolving family conflicts & Vastu corrections',NULL,NULL,NULL,12,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(13,'chat','topic','Effective everyday remedies & spiritual healing',NULL,NULL,NULL,13,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(14,'chat','service_tab','Why Chat Online?','Why choose online astrology chat over a phone call?','Free chat consultation provides a level of ease that many people don\'t find in phone calls. You can chat with an astrologer discreetly from the comfort of your house or even at your workplace without the fear of being overheard. What\'s more is that you get to keep a written record of all your predictions and remedies that you can revisit whenever you want. It is a stress-free private astrology consultation option for those with speaking difficulties or people trying to avoid background noise.',NULL,14,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(15,'chat','service_tab','Love & Relationship','Chat With An Astrologer For Love And Relationship','Chat with an astrologer for love advice, relationship guidance, and to find the \'perfect one.\' Restore harmony in your relationship with free chat. Whether you are planning to tie the knot, avail Kundli Matching chat to find your life partner, or check compatibility with just one chat with an expert astrologer.',NULL,15,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(16,'chat','service_tab','Career & Finance','Chat With An Astrologer For Career And Finance','Career astrology chat can help you out of a professional rut. Chat now and find the right time to start a new job or business, or know the exact time of promotion. Confused about where to invest your money or struggling to save up for the future? Financial astrology chat is all you need. Start chat now!',NULL,16,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(17,'chat','service_tab','How To Start?','How To Chat With An Astrologer On AstroHero?','Chat with an astrologer online for quick solutions to your problems. How? In four simple steps, and in under a minute, you can set up your account and start chatting:\n\n<ul><li>Sign up or log in to your account.</li><li>Browse verified astrologers by expertise, rating, or language.</li><li>Select your astrologer and start your free consultation.</li><li>Get a personalized consultation and save it for reference.</li></ul>',NULL,17,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(18,'chat','service_tab','India\'s #1 Platform','Why AstroHero Is India\'s #1 Platform','With thousands of verified astrologers on the platform, we are committed to providing top-notch services. All astrologers go through a rigorous screening process. Our chat option is available 24*7 in multiple languages, ensuring you always find the right expert without language barriers. We provide end-to-end encrypted, 100% confidential chat support.',NULL,18,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(19,'chat','faq','Is my first astrology chat session completely free?',NULL,'Yes! As a new user on AstroHero, you get a complimentary first chat session. You can connect with our premium astrologers instantly to experience our guidance without any upfront payment.',NULL,19,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(20,'chat','faq','How do I know if an astrologer is genuine?',NULL,'Every astrologer on our platform goes through a strict 4-step verification process. We conduct thorough background checks and live panel interviews to ensure you only speak with authentic, highly qualified experts.',NULL,20,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(21,'chat','faq','Are chat consultations as effective as phone calls?',NULL,'Absolutely. Chat sessions offer the exact same level of accuracy as calls. In fact, they provide more privacy and give you a written record of all predictions and remedies that you can refer back to anytime.',NULL,21,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(22,'chat','faq','Will I receive specific remedies during the chat?',NULL,'Yes, our astrologers provide highly personalized and practical remedies—such as specific gemstone advice, powerful mantras, and easy daily rituals—tailored precisely to your unique birth chart.',NULL,22,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(23,'chat','faq','What details do I need to provide for a consultation?',NULL,'For the most accurate reading, you simply need to share your exact date of birth, time of birth, and place of birth. Our experts will use these details to generate your Kundli instantly and answer your queries.',NULL,23,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(24,'talk','feature','Verified',NULL,'Real astrologers trusted by <strong>5Cr+</strong> users across India and <strong>60+</strong> countries.','star',1,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(25,'talk','feature','Experienced',NULL,'Every astrologer clears a rigorous <strong>4-step verification</strong> before taking a single call.','graduation',2,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(26,'talk','feature','Trusted',NULL,'Your first call is free. Not satisfied? Switch to another astrologer anytime.','check-circle',3,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(27,'talk','verify_step','Background & KYC Checks',NULL,'We strictly verify government documents, real identity, and address before any astrologer is considered.',NULL,4,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(28,'talk','verify_step','Certification Review',NULL,'Astrological degrees, authentic lineage proof, and years of valid experience are thoroughly evaluated.',NULL,5,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(29,'talk','verify_step','Live Assessment Panel',NULL,'Candidates face a tough, real-time consultation test conducted by our in-house veteran astrologers.',NULL,6,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(30,'talk','verify_step','Quality Monitoring',NULL,'Approved experts undergo a strict trial period where consultations are continuously audited for accuracy.',NULL,7,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(31,'talk','topic','Finding true love & soulmate compatibility',NULL,NULL,NULL,8,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(32,'talk','topic','Perfect timing for marriage & Kundli analysis',NULL,NULL,NULL,9,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(33,'talk','topic','Navigating career shifts & promotion timelines',NULL,NULL,NULL,10,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(34,'talk','topic','Wealth creation & strategic business investments',NULL,NULL,NULL,11,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(35,'talk','topic','Resolving family conflicts & Vastu corrections',NULL,NULL,NULL,12,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(36,'talk','topic','Effective everyday remedies & spiritual healing',NULL,NULL,NULL,13,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(37,'talk','service_tab','Why Call Online?','Why choose an online astrology call over a physical meeting?','Free call consultation provides a level of ease that many people don\'t find elsewhere. You can call an astrologer discreetly from the comfort of your house or even at your workplace. What\'s more is that you get to keep an audio record of all your predictions and remedies that you can revisit whenever you want. It is a stress-free private astrology consultation option.',NULL,14,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(38,'talk','service_tab','Love & Relationship','Call An Astrologer For Love And Relationship','Call an astrologer for love advice, relationship guidance, and to find the \'perfect one.\' Restore harmony in your relationship with a free call. Whether you are planning to tie the knot, avail Kundli Matching on a call to find your life partner, or check compatibility with just one call with an expert astrologer.',NULL,15,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(39,'talk','service_tab','Career & Finance','Call An Astrologer For Career And Finance','Career astrology call can help you out of a professional rut. Call now and find the right time to start a new job or business, or know the exact time of promotion. Confused about where to invest your money or struggling to save up for the future? Financial astrology on call is all you need. Start calling now!',NULL,16,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(40,'talk','service_tab','How To Start?','How To Call An Astrologer On AstroHero?','Call an astrologer online for quick solutions to your problems. How? In four simple steps, and in under a minute, you can set up your account and start calling:\n\n<ul><li>Sign up or log in to your account.</li><li>Browse verified astrologers by expertise, rating, or language.</li><li>Select your astrologer and start your free consultation.</li><li>Get a personalized consultation and save it for reference.</li></ul>',NULL,17,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(41,'talk','service_tab','India\'s #1 Platform','Why AstroHero Is India\'s #1 Platform','With thousands of verified astrologers on the platform, we are committed to providing top-notch services. All astrologers go through a rigorous screening process. Our calling option is available 24*7 in multiple languages, ensuring you always find the right expert without language barriers. We provide end-to-end encrypted, 100% confidential call support.',NULL,18,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(42,'talk','faq','Is my first astrology call session completely free?',NULL,'Yes! As a new user on AstroHero, you get a complimentary first call session. You can connect with our premium astrologers instantly to experience our guidance without any upfront payment.',NULL,19,1,'2026-10-03 06:14:38','2026-10-03 06:30:37'),(43,'talk','faq','How do I know if an astrologer is genuine?',NULL,'Every astrologer on our platform goes through a strict 4-step verification process. We conduct thorough background checks and live panel interviews to ensure you only speak with authentic, highly qualified experts.',NULL,20,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(44,'talk','faq','Are online call consultations as effective as physical meetings?',NULL,'Absolutely. Online call sessions offer the exact same level of accuracy as face-to-face meetings. In fact, they provide more privacy and give you the flexibility to get predictions and remedies that you can refer back to anytime.',NULL,21,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(45,'talk','faq','Will I receive specific remedies during the call?',NULL,'Yes, our astrologers provide highly personalized and practical remedies—such as specific gemstone advice, powerful mantras, and easy daily rituals—tailored precisely to your unique birth chart.',NULL,22,1,'2026-10-03 06:14:38','2026-10-03 06:14:38'),(46,'talk','faq','What details do I need to provide for a consultation?',NULL,'For the most accurate reading, you simply need to share your exact date of birth, time of birth, and place of birth. Our experts will use these details to generate your Kundli instantly and answer your queries.',NULL,23,1,'2026-10-03 06:14:38','2026-10-03 06:14:38');
